=================== E164Telephone.java ===================
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Converts a supplied telephone into E.164 form. Spaces, dashes and brackets are stripped; a leading
 * '+' with its country code is kept when present, otherwise country code '+61' is assumed and a single
 * leading '0' is dropped from the national digits. The result must carry 8 to 15 digits after the '+',
 * otherwise it cannot form a valid E.164 number and an {@link InvalidTelephoneException} (400) is thrown.
 */
final class E164Telephone {

    private E164Telephone() {
    }

    static String normalize(String telephone) throws InvalidTelephoneException {
        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\[\\]-]", "");
        boolean hasPlus = cleaned.startsWith("+");
        String rest = hasPlus ? cleaned.substring(1) : cleaned;
        if (rest.isEmpty() || !rest.chars().allMatch(Character::isDigit)) {
            throw new InvalidTelephoneException(telephone);
        }
        String digits;
        if (hasPlus) {
            digits = rest;
        }
        else {
            String national = rest.startsWith("0") ? rest.substring(1) : rest;
            digits = "61" + national;
        }
        if (digits.length() < 8 || digits.length() > 15) {
            throw new InvalidTelephoneException(telephone);
        }
        return "+" + digits;
    }
}

=================== AddressNormalizer.java ===================
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Canonical normalization for an owner's {@code address}. Whitespace is trimmed and every run of
 * whitespace collapsed to a single space, the text is upper-cased, and common abbreviations are
 * expanded on a whole-word basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
 * The transform is idempotent, so normalizing an already-normalized address returns it unchanged.
 *
 * <p>Applied whenever an owner is created (see {@link ValidateOwnerFields}) so the stored and returned
 * {@code address} is the normalized string, and reused wherever addresses are compared
 * ({@link EnsureUniqueHousehold}, {@link AssignHousehold}) so those comparisons see the same form.
 */
final class AddressNormalizer {

    private AddressNormalizer() {
    }

    static String normalize(String address) {
        if (address == null) {
            return "";
        }
        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.split(" ");
        StringBuilder sb = new StringBuilder(collapsed.length());
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(expand(tokens[i]));
        }
        return sb.toString();
    }

    private static String expand(String token) {
        switch (token) {
            case "ST":
                return "STREET";
            case "RD":
                return "ROAD";
            case "AVE":
                return "AVENUE";
            default:
                return token;
        }
    }
}

